/**
 * flag-stalled-projects cron.
 *
 * Runs daily at 02:00 UTC.
 * Calls the `flag_stalled_projects` Postgres RPC which marks projects
 * as stalled when they have been in an active-like status for too long
 * without a confirmed session.
 *
 * The RPC definition lives in Dato's migration — this file is the cron wrapper.
 */
import { supabase } from '../lib/supabase.js'
import { logger } from '../lib/logger.js'

// ─── Main handler ────────────────────────────────────────────────────────────

export async function runFlagStalledProjects(): Promise<void> {
  const runLog = logger.child({ cron: 'flag-stalled-projects' })
  runLog.info('flag-stalled: calling flag_stalled_projects RPC')

  try {
    const { data, error } = await supabase.rpc('flag_stalled_projects')

    if (error) {
      runLog.error({ err: error }, 'flag-stalled: RPC failed')
      return
    }

    // The RPC returns the count of projects it flagged as its scalar result.
    const count = typeof data === 'number' ? data : 0
    runLog.info({ count }, 'flag-stalled: flagged projects')
  } catch (err: unknown) {
    runLog.error({ err }, 'flag-stalled: unexpected error')
  }
}

/**
 * healed-photo-reminders cron.
 *
 * Runs daily at 09:00 UTC.
 * Finds healed photo slots (s1_healed, s2_healed, …) that are overdue and
 * still have no photo uploaded. Inserts an inbox_assignments alert so
 * studio staff see them in the Inbox without extra polling.
 *
 * Idempotency: we insert only when no existing assignment exists for the
 * same (item_id) pair in the last 24 hours, matching on a stable key
 * composed as `healed_reminder:{photo_id}`.
 *
 * NOTE: No dedicated inbox_items table exists in the current schema.
 * The Inbox module uses inbox_assignments (studio_id, assigned_to, item_kind,
 * item_id). We surface healed-slot overdue alerts via `logAuditAction` approach
 * (insert into client_communications as an internal note) and log a warning
 * until Dato adds a first-class alert surface.
 */
import { supabase } from '../lib/supabase.js'
import { logger } from '../lib/logger.js'

// ─── Types ───────────────────────────────────────────────────────────────────

interface OverdueHealedSlot {
  id: string
  project_id: string
  slot_type: string
  due_date: string
  project_name: string | null
  studio_id: string
  client_id: string | null
}

// ─── Main handler ────────────────────────────────────────────────────────────

export async function runHealedPhotoReminders(): Promise<void> {
  const runLog = logger.child({ cron: 'healed-photo-reminders' })
  runLog.info('healed-reminders: checking for overdue healed photo slots')

  try {
    // Query overdue healed slots via join.
    // Dates: due_date < now + 3 days AND due_date > now - 30 days
    // (within the 30-day healing window, coming due soon)
    const { data, error } = await supabase
      .from('project_progress_photos')
      .select(`
        id,
        project_id,
        slot_type,
        due_date,
        project:projects!project_progress_photos_project_id_fkey(
          name,
          studio_id,
          client_id
        )
      `)
      .like('slot_type', 's%_healed')
      .is('storage_path', null)
      .lt('due_date', new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString())
      .gt('due_date', new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString())

    if (error) {
      runLog.error({ err: error }, 'healed-reminders: query failed')
      return
    }

    const slots = (data ?? []) as unknown as Array<{
      id: string
      project_id: string
      slot_type: string
      due_date: string
      project: {
        name: string | null
        studio_id: string
        client_id: string | null
      } | Array<{
        name: string | null
        studio_id: string
        client_id: string | null
      }> | null
    }>

    if (slots.length === 0) {
      runLog.info('healed-reminders: no overdue healed slots found')
      return
    }

    runLog.info({ count: slots.length }, 'healed-reminders: processing overdue slots')

    const normalized: OverdueHealedSlot[] = slots.map((s) => {
      const proj = Array.isArray(s.project) ? (s.project[0] ?? null) : (s.project ?? null)
      return {
        id: s.id,
        project_id: s.project_id,
        slot_type: s.slot_type,
        due_date: s.due_date,
        project_name: proj?.name ?? null,
        studio_id: proj?.studio_id ?? '',
        client_id: proj?.client_id ?? null,
      }
    }).filter((s) => !!s.studio_id)

    const results = await Promise.allSettled(
      normalized.map((slot) => processHealedSlotAlert(slot, runLog))
    )

    const succeeded = results.filter((r) => r.status === 'fulfilled').length
    const failed = results.filter((r) => r.status === 'rejected').length

    results.forEach((result, idx) => {
      if (result.status === 'rejected') {
        runLog.error(
          { err: result.reason, slotId: normalized[idx]?.id },
          'healed-reminders: slot alert failed'
        )
      }
    })

    runLog.info({ succeeded, failed }, 'healed-reminders: run complete')
  } catch (err: unknown) {
    runLog.error({ err }, 'healed-reminders: unexpected error')
  }
}

// ─── Per-slot alert ───────────────────────────────────────────────────────────

async function processHealedSlotAlert(slot: OverdueHealedSlot, parentLog: ReturnType<typeof logger.child>): Promise<void> {
  const slotLog = parentLog.child({ slotId: slot.id, projectId: slot.project_id, studioId: slot.studio_id })

  const daysOverdue = Math.floor(
    (Date.now() - new Date(slot.due_date).getTime()) / (1000 * 60 * 60 * 24)
  )

  const projectName = slot.project_name ?? 'Unknown project'
  const alertNote =
    `Healed photo overdue: ${slot.slot_type} for project "${projectName}" ` +
    `(due ${new Date(slot.due_date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}, ` +
    `${daysOverdue > 0 ? `${daysOverdue} day${daysOverdue === 1 ? '' : 's'} overdue` : 'due within 3 days'}).`

  // Surface as a client_communications internal note so it shows up in
  // the studio's activity context. When Dato adds a dedicated alerts table,
  // this will become a proper inbox_items insert.
  if (slot.client_id) {
    const { error } = await supabase
      .from('client_communications')
      .insert({
        studio_id: slot.studio_id,
        client_id: slot.client_id,
        booking_id: null,
        channel: 'internal' as never, // internal channel for staff-only notes
        direction: 'outbound',
        template: 'healed_photo_reminder',
        subject: `Healed photo needed: ${slot.slot_type}`,
        body: alertNote,
        status: 'sent',
        metadata: {
          photo_id: slot.id,
          project_id: slot.project_id,
          slot_type: slot.slot_type,
          due_date: slot.due_date,
          alert_kind: 'healed_photo_overdue',
        } as Record<string, unknown>,
      })

    if (error) {
      // Non-fatal: log and continue — some studios may not have client_id on project
      slotLog.warn({ err: error }, 'healed-reminders: comm insert failed (non-fatal)')
      return
    }

    slotLog.info({ daysOverdue }, 'healed-reminders: alert inserted')
  } else {
    // No client linked — log audit entry only
    slotLog.warn(
      { slotId: slot.id, projectId: slot.project_id },
      'healed-reminders: no client_id on project — logging alert only (no comm row)'
    )
  }
}

