/**
 * fetch-moodboard-thumbnail BullMQ worker — Sprint 6.
 *
 * Consumes `fetch-moodboard-thumbnail` jobs enqueued when a URL is added
 * to project_references. Unfurls the URL to extract og:image or
 * twitter:image and stores it as thumbnail_url on the reference row.
 *
 * Idempotent: if thumbnail_url is already set or external_url is null, returns early.
 * Retry: 3 attempts, exponential backoff (5s base). Timeout 10s per fetch.
 * No retry on 4xx HTTP errors (dead URLs).
 */
import { Worker } from 'bullmq'
import { supabase } from '../lib/supabase.js'
import { logger } from '../lib/logger.js'
import { workerEnv } from '../lib/env.js'

const QUEUE_NAME = 'inkos-jobs'
const JOB_NAME = 'fetch-moodboard-thumbnail'
const FETCH_TIMEOUT_MS = 10_000

// ─── Payload type ─────────────────────────────────────────────────────────────

interface FetchMoodboardThumbnailPayload {
  reference_id: string
}

function isFetchMoodboardPayload(data: unknown): data is FetchMoodboardThumbnailPayload {
  return (
    typeof data === 'object' &&
    data !== null &&
    typeof (data as Record<string, unknown>)['reference_id'] === 'string'
  )
}

// ─── Open Graph extraction ────────────────────────────────────────────────────

/**
 * Fetch a URL and extract og:image or twitter:image from meta tags.
 * Uses an AbortController for the 10s timeout.
 * Throws on network failures (so BullMQ retries). Returns null on 4xx.
 */
async function extractThumbnailUrl(url: string): Promise<string | null> {
  const controller = new AbortController()
  const timeoutId = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS)

  let html: string
  try {
    const response = await fetch(url, {
      signal: controller.signal,
      headers: {
        'User-Agent': 'InkOS-Bot/1.0 (+https://inkos.app)',
        Accept: 'text/html',
      },
    })

    clearTimeout(timeoutId)

    // Don't retry on client errors (dead link, auth-required, etc.)
    if (response.status >= 400 && response.status < 500) {
      return null
    }

    if (!response.ok) {
      throw new Error(`HTTP ${response.status} fetching ${url}`)
    }

    // Read only the first 64KB — og:image is always in <head>
    const reader = response.body?.getReader()
    if (!reader) return null

    const chunks: Uint8Array[] = []
    let totalBytes = 0
    const MAX_BYTES = 64 * 1024

    while (totalBytes < MAX_BYTES) {
      const { done, value } = await reader.read()
      if (done) break
      if (value) {
        chunks.push(value)
        totalBytes += value.length
      }
    }
    reader.cancel().catch(() => undefined)

    html = new TextDecoder().decode(
      chunks.reduce((acc, chunk) => {
        const merged = new Uint8Array(acc.length + chunk.length)
        merged.set(acc)
        merged.set(chunk, acc.length)
        return merged
      }, new Uint8Array(0))
    )
  } catch (err: unknown) {
    clearTimeout(timeoutId)
    if (err instanceof Error && err.name === 'AbortError') {
      throw new Error(`Timeout fetching ${url} after ${FETCH_TIMEOUT_MS}ms`)
    }
    throw err
  }

  // Parse meta tags with simple regex — avoids a full DOM parser dependency.
  // Priority: og:image > twitter:image
  const ogImageMatch = html.match(
    /<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i
  ) ?? html.match(
    /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i
  )
  if (ogImageMatch?.[1]) return ogImageMatch[1]

  const twitterImageMatch = html.match(
    /<meta[^>]+name=["']twitter:image["'][^>]+content=["']([^"']+)["']/i
  ) ?? html.match(
    /<meta[^>]+content=["']([^"']+)["'][^>]+name=["']twitter:image["']/i
  )
  if (twitterImageMatch?.[1]) return twitterImageMatch[1]

  return null
}

// ─── Worker ──────────────────────────────────────────────────────────────────

export function createFetchMoodboardThumbnailWorker() {
  const worker = new Worker(
    QUEUE_NAME,
    async (job) => {
      if (job.name !== JOB_NAME) return

      if (!isFetchMoodboardPayload(job.data)) {
        logger.error(
          { jobId: job.id, data: job.data },
          'fetch-moodboard-thumbnail: invalid payload — skipping'
        )
        return
      }

      const { reference_id } = job.data
      const workerLog = logger.child({ jobId: job.id, referenceId: reference_id })
      workerLog.info('fetch-moodboard-thumbnail: processing')

      // ── 1. Fetch the reference row ────────────────────────────────────────
      const { data: ref, error: fetchErr } = await supabase
        .from('project_references')
        .select('id, external_url, thumbnail_url')
        .eq('id', reference_id)
        .maybeSingle()

      if (fetchErr || !ref) {
        workerLog.error({ err: fetchErr }, 'fetch-moodboard-thumbnail: reference row not found')
        // Don't retry — the row was deleted or never existed
        return
      }

      // ── 2. Idempotency guard ──────────────────────────────────────────────
      if (!ref.external_url) {
        workerLog.info('fetch-moodboard-thumbnail: no external_url — skipping')
        return
      }

      if (ref.thumbnail_url) {
        workerLog.info('fetch-moodboard-thumbnail: thumbnail_url already set — skipping (idempotent)')
        return
      }

      // ── 3. Unfurl URL ─────────────────────────────────────────────────────
      const externalUrl = ref.external_url as string

      let thumbnailUrl: string | null = null
      try {
        thumbnailUrl = await extractThumbnailUrl(externalUrl)
      } catch (err: unknown) {
        // Re-throw network/timeout errors so BullMQ retries
        workerLog.error({ err, url: externalUrl }, 'fetch-moodboard-thumbnail: unfurl failed — will retry')
        throw err
      }

      if (!thumbnailUrl) {
        workerLog.info({ url: externalUrl }, 'fetch-moodboard-thumbnail: no og:image found — not an error')
        return
      }

      // ── 4. Persist thumbnail_url ──────────────────────────────────────────
      const { error: updateErr } = await supabase
        .from('project_references')
        .update({ thumbnail_url: thumbnailUrl } as never)
        .eq('id', reference_id)

      if (updateErr) {
        workerLog.error({ err: updateErr }, 'fetch-moodboard-thumbnail: DB update failed — will retry')
        throw new Error(`DB update failed: ${updateErr.message}`)
      }

      workerLog.info({ thumbnailUrl }, 'fetch-moodboard-thumbnail: thumbnail saved')
    },
    {
      connection: {
        url: workerEnv.REDIS_URL,
        maxRetriesPerRequest: null,
      },
      concurrency: 3,
    }
  )

  worker.on('completed', (job) => {
    logger.info({ jobId: job.id }, 'fetch-moodboard-thumbnail: job completed')
  })

  worker.on('failed', (job, err) => {
    logger.error({ jobId: job?.id, err }, 'fetch-moodboard-thumbnail: job failed')
  })

  worker.on('error', (err) => {
    logger.error({ err }, 'fetch-moodboard-thumbnail worker: error')
  })

  return worker
}

/**
 * send-deposit-link BullMQ worker — Sprint 6.
 *
 * Consumes `send-deposit-link` jobs enqueued after a Dodo checkout is created
 * for a project deposit. Delivers the checkout link to the client via email
 * (Resend) or SMS (Twilio).
 *
 * Retry strategy:
 *   - No retry on 4xx (bad email/phone, unsubscribed).
 *   - Retry 3× exponential on 5xx / network failures.
 *
 * Job payload: { project_id, client_id, checkout_url, amount_cents, channel }
 */
import { Worker } from 'bullmq'
import { Resend } from 'resend'
import { Twilio } from 'twilio'
import { supabase } from '../lib/supabase.js'
import { logger } from '../lib/logger.js'
import { workerEnv } from '../lib/env.js'

const QUEUE_NAME = 'inkos-jobs'
const JOB_NAME = 'send-deposit-link'

// ─── Payload type ─────────────────────────────────────────────────────────────

interface SendDepositLinkPayload {
  project_id: string
  client_id: string
  checkout_url: string
  amount_cents: number
  channel: 'email' | 'sms'
}

function isSendDepositLinkPayload(data: unknown): data is SendDepositLinkPayload {
  if (typeof data !== 'object' || data === null) return false
  const d = data as Record<string, unknown>
  return (
    typeof d['project_id'] === 'string' &&
    typeof d['client_id'] === 'string' &&
    typeof d['checkout_url'] === 'string' &&
    typeof d['amount_cents'] === 'number' &&
    (d['channel'] === 'email' || d['channel'] === 'sms')
  )
}

// ─── Lazy clients ─────────────────────────────────────────────────────────────

let _resend: Resend | null = null
function getResend(): Resend | null {
  if (!workerEnv.RESEND_API_KEY) return null
  if (!_resend) _resend = new Resend(workerEnv.RESEND_API_KEY)
  return _resend
}

let _twilio: Twilio | null = null
function getTwilio(): Twilio | null {
  if (!workerEnv.TWILIO_ACCOUNT_SID || !workerEnv.TWILIO_AUTH_TOKEN) return null
  if (!_twilio) _twilio = new Twilio(workerEnv.TWILIO_ACCOUNT_SID, workerEnv.TWILIO_AUTH_TOKEN)
  return _twilio
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function formatCents(cents: number): string {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(cents / 100)
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

function buildEmailHtml(params: {
  clientFirstName: string
  projectName: string
  studioName: string
  amountFormatted: string
  checkoutUrl: string
}): string {
  const { clientFirstName, projectName, studioName, amountFormatted, checkoutUrl } = params
  const safeStudio = escapeHtml(studioName)
  const safeProject = escapeHtml(projectName)
  const safeClient = escapeHtml(clientFirstName)
  const safeAmount = escapeHtml(amountFormatted)
  const safeUrl = escapeHtml(checkoutUrl)

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <title>Deposit link — ${safeStudio}</title>
</head>
<body style="margin:0;padding:32px 16px;background:#F7F7F5;font-family:Inter,sans-serif;color:#0F0F0F;">
  <div style="max-width:480px;margin:0 auto;background:#F7F7F5;">
    <p style="font-size:13px;color:#787774;margin:0 0 4px;">From ${safeStudio}</p>
    <h1 style="font-size:22px;font-weight:700;margin:0 0 16px;">${safeProject} — deposit</h1>
    <p style="font-size:14px;line-height:1.6;margin:0 0 24px;">
      Hi ${safeClient},<br/><br/>
      Your deposit of <strong>${safeAmount}</strong> is ready.
      Use the link below to pay securely.
    </p>
    <a
      href="${safeUrl}"
      style="display:inline-block;background:#0F0F0F;color:#F7F7F5;text-decoration:none;padding:12px 24px;border-radius:6px;font-size:14px;font-weight:600;"
    >Pay deposit — ${safeAmount}</a>
    <p style="font-size:12px;color:#787774;margin:24px 0 0;">
      This link is single-use and will expire. If you have questions,
      reply to this email or contact ${safeStudio} directly.
    </p>
  </div>
</body>
</html>`
}

// ─── Non-retryable error guard ────────────────────────────────────────────────

/**
 * Returns true when the error is a client error (4xx) that should NOT be retried.
 * Resend and Twilio both surface status codes in their error objects.
 */
function isClientError(err: unknown): boolean {
  if (typeof err !== 'object' || err === null) return false
  const e = err as Record<string, unknown>
  const status = typeof e['statusCode'] === 'number' ? e['statusCode']
    : typeof e['status'] === 'number' ? e['status']
    : null
  return status !== null && status >= 400 && status < 500
}

// ─── Worker ──────────────────────────────────────────────────────────────────

export function createSendDepositLinkWorker() {
  const worker = new Worker(
    QUEUE_NAME,
    async (job) => {
      if (job.name !== JOB_NAME) return

      if (!isSendDepositLinkPayload(job.data)) {
        logger.error(
          { jobId: job.id, data: job.data },
          'send-deposit-link: invalid payload — skipping'
        )
        return
      }

      const { project_id, client_id, checkout_url, amount_cents, channel } = job.data
      const workerLog = logger.child({ jobId: job.id, projectId: project_id, channel })
      workerLog.info('send-deposit-link: processing')

      // ── 1. Fetch client contact ───────────────────────────────────────────
      const { data: client, error: clientErr } = await supabase
        .from('clients')
        .select('id, first_name, last_name, email, phone')
        .eq('id', client_id)
        .maybeSingle()

      if (clientErr || !client) {
        workerLog.error({ err: clientErr }, 'send-deposit-link: client not found — skipping')
        return
      }

      // ── 2. Fetch project name + studio name ───────────────────────────────
      const { data: project, error: projectErr } = await supabase
        .from('projects')
        .select('name, studio_id, studio:studios!projects_studio_id_fkey(name)')
        .eq('id', project_id)
        .maybeSingle()

      if (projectErr || !project) {
        workerLog.error({ err: projectErr }, 'send-deposit-link: project not found — skipping')
        return
      }

      const studioRaw = project.studio
      const studioName: string = (() => {
        if (!studioRaw) return 'the studio'
