        return (studioRaw as { name?: string }).name ?? 'the studio'
      })()

      const projectName = project.name ?? 'your project'
      const clientFirstName = client.first_name ?? 'there'
      const amountFormatted = formatCents(amount_cents)

      // ── 3. Deliver ────────────────────────────────────────────────────────
      if (channel === 'email') {
        const clientEmail = client.email
        if (!clientEmail) {
          workerLog.warn({ clientId: client_id }, 'send-deposit-link: client has no email — skipping')
          return
        }

        const resend = getResend()
        if (!resend) {
          workerLog.warn('send-deposit-link: Resend not configured (RESEND_API_KEY missing) — skipping')
          return
        }

        const html = buildEmailHtml({
          clientFirstName,
          projectName,
          studioName,
          amountFormatted,
          checkoutUrl: checkout_url,
        })

        try {
          const result = await resend.emails.send({
            from: workerEnv.RESEND_FROM_EMAIL,
            to: clientEmail,
            replyTo: workerEnv.RESEND_REPLY_TO,
            subject: `Deposit link for ${projectName}`,
            html,
          })

          if (result.error) {
            const err = result.error as unknown as Record<string, unknown>
            if (isClientError(err)) {
              workerLog.warn({ err: result.error }, 'send-deposit-link: email 4xx — not retrying')
              return
            }
            throw new Error(`Resend error: ${JSON.stringify(result.error)}`)
          }

          workerLog.info({ emailId: result.data?.id }, 'send-deposit-link: email sent via Resend')
        } catch (err: unknown) {
          if (isClientError(err)) {
            workerLog.warn({ err }, 'send-deposit-link: email 4xx — not retrying')
            return
          }
          workerLog.error({ err }, 'send-deposit-link: email failed — will retry')
          throw err
        }

      } else {
        // channel === 'sms'
        const clientPhone = client.phone
        if (!clientPhone) {
          workerLog.warn({ clientId: client_id }, 'send-deposit-link: client has no phone — skipping')
          return
        }

        const twilioClient = getTwilio()
        if (!twilioClient) {
          workerLog.warn('send-deposit-link: Twilio not configured — skipping')
          return
        }

        if (!workerEnv.TWILIO_PHONE_NUMBER) {
          workerLog.warn('send-deposit-link: TWILIO_PHONE_NUMBER not set — skipping')
          return
        }

        const smsBody =
          `Hi ${clientFirstName}, your deposit of ${amountFormatted} for ${projectName} at ${studioName} ` +
          `is ready to pay: ${checkout_url}`

        try {
          const message = await twilioClient.messages.create({
            from: workerEnv.TWILIO_PHONE_NUMBER,
            to: clientPhone,
            body: smsBody,
          })

          workerLog.info({ sid: message.sid }, 'send-deposit-link: SMS sent via Twilio')
        } catch (err: unknown) {
          if (isClientError(err)) {
            workerLog.warn({ err }, 'send-deposit-link: SMS 4xx — not retrying')
            return
          }
          workerLog.error({ err }, 'send-deposit-link: SMS failed — will retry')
          throw err
        }
      }
    },
    {
      connection: {
        url: workerEnv.REDIS_URL,
        maxRetriesPerRequest: null,
      },
      concurrency: 5,
    }
  )

  worker.on('completed', (job) => {
    logger.info({ jobId: job.id }, 'send-deposit-link: job completed')
  })

  worker.on('failed', (job, err) => {
    logger.error({ jobId: job?.id, err }, 'send-deposit-link: job failed')
  })

  worker.on('error', (err) => {
    logger.error({ err }, 'send-deposit-link worker: error')
  })

  return worker
}

