import { NextRequest, NextResponse } from 'next/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { listProjects } from '@/lib/projects/queries'
import { logger } from '@/lib/logger'
import type { ListProjectsFilters, ProjectStatus } from '@/lib/projects/queries'

const VALID_STATUSES: ProjectStatus[] = [
  'active',
  'completed',
  'on_hold',
  'cancelled',
  'deposit_paid',
  'healing',
  'archived',
]

function parseStatusCsv(param: string | null): ProjectStatus[] {
  if (!param) return []
  return param
    .split(',')
    .map((s) => s.trim() as ProjectStatus)
    .filter((s) => VALID_STATUSES.includes(s))
}

export async function GET(req: NextRequest) {
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { searchParams } = new URL(req.url)
  const filters: ListProjectsFilters = {}

  // Single status filter (backward-compat) — overridden if status_csv is provided
  const statusParam = searchParams.get('status')
  const statusCsvParam = searchParams.get('status')  // also handles CSV via same param
  if (statusParam) {
    const statuses = parseStatusCsv(statusCsvParam)
    if (statuses.length === 1) {
      filters.status = statuses[0]
    } else if (statuses.length > 1) {
      filters.statuses = statuses
    }
  }

  // status_excludes — comma-separated statuses to exclude
  // Default: excludes archived and cancelled so booking UI shows only actionable projects
  const statusExcludesParam = searchParams.get('status_excludes')
  const statusExcludes = parseStatusCsv(
    statusExcludesParam ?? 'archived,cancelled'
  )
  if (statusExcludes.length > 0 && !filters.status && !filters.statuses) {
    filters.statusExcludes = statusExcludes
  }

  // client_id — filter to projects for a specific client (snake_case, booking-UI convention)
  const clientIdParam = searchParams.get('client_id') ?? searchParams.get('clientId')
  if (clientIdParam) filters.clientId = clientIdParam

  const artistId = searchParams.get('artistId') ?? searchParams.get('artist_id')
  if (artistId) filters.artistId = artistId

  const search = searchParams.get('search')
  if (search) filters.search = search

  try {
    const projects = await listProjects(auth.studioId, filters)
    return NextResponse.json({ data: projects })
  } catch (err) {
    logger.error({ err }, 'GET /api/projects failed')
    return NextResponse.json({ error: 'Failed to fetch projects' }, { status: 500 })
  }
}

